using UnityEngine;
using NWH.WheelController3D;
namespace LWS.TruckSports {
// Shared NWH wheel adapter for new arcade courses; never clamps world momentum to a local reverse limit.
public sealed class SportsEventTruck:MonoBehaviour {
 public SportsNwhTractorMotor tractorMotor;public Rigidbody body;public BoxCollider shape;public WheelController[] wheels;public Renderer paint;public Transform visuals;public AudioSource engine;public SportsEventSession session;public int slot;
 public float motorTorque=8,brakeTorque=24,maxSpeed=23,reverseSpeed=7,steerAngle=32,grip=1.2f;public bool Powered{get;private set;}public bool Grounded{get;private set;}public Vector2 command;bool opposite;Renderer[] paintParts;MaterialPropertyBlock colorBlock;
 void Awake(){colorBlock=new MaterialPropertyBlock();var all=visuals.GetComponentsInChildren<Renderer>(true);var parts=new System.Collections.Generic.List<Renderer>();foreach(var r in all)if(r.name=="Cab")parts.Add(r);if(parts.Count==0)parts.Add(paint);paintParts=parts.ToArray();}
 public void ApplyColor(Color color){if(colorBlock==null)Awake();colorBlock.SetColor("_BaseColor",color);colorBlock.SetColor("_Color",color);foreach(var r in paintParts)r.SetPropertyBlock(colorBlock);}
 public void Prepare(Vector3 position,Quaternion rotation,bool powered=true){gameObject.SetActive(true);body.isKinematic=false;body.detectCollisions=true;body.position=position;body.rotation=rotation;transform.SetPositionAndRotation(position,rotation);body.linearVelocity=body.angularVelocity=Vector3.zero;if(tractorMotor!=null)tractorMotor.ResetAttachedBodies();command=Vector2.zero;opposite=false;Power(powered);ApplyColor(session.setup.players[slot].color);body.WakeUp();}
 public void Power(bool powered){Powered=powered;if(tractorMotor!=null){tractorMotor.Power(powered);return;}foreach(var w in wheels){w.MotorTorque=w.BrakeTorque=0;w.SteerAngle=0;w.enabled=powered;if(w.wheel.meshCollider!=null)w.wheel.meshCollider.enabled=powered;if(powered){w.wheel.angularVelocity=0;w.WakeFromSleep();}}}
 public void Park(Vector3 p){Power(false);if(!body.isKinematic)body.linearVelocity=body.angularVelocity=Vector3.zero;body.isKinematic=true;body.detectCollisions=false;body.position=p;body.rotation=Quaternion.identity;transform.SetPositionAndRotation(p,Quaternion.identity);command=Vector2.zero;StopSound();}
 public void TickDrive(Vector2 drive){command=drive;if(!Powered||body.isKinematic)return;if(tractorMotor!=null){tractorMotor.Drive(drive);Grounded=tractorMotor.Grounded;return;}float speed=Vector3.Dot(body.linearVelocity,body.rotation*Vector3.forward);if(drive.y*speed>=0||Mathf.Abs(speed)<.12f)opposite=false;else if(Mathf.Abs(speed)>.3f)opposite=true;Grounded=false;for(int i=0;i<wheels.Length;i++){var w=wheels[i];Grounded|=w.IsGrounded;w.MotorTorque=opposite||speed*(drive.y<0?-1:1)>=(drive.y<0?reverseSpeed:maxSpeed)?0:drive.y*motorTorque;w.BrakeTorque=opposite?Mathf.Abs(drive.y)*brakeTorque:0;w.SteerAngle=i<2?drive.x*steerAngle:0;w.LongitudinalFrictionGrip=w.LateralFrictionGrip=grip;}}
 void Update(){if(engine==null)return;float volume=session.Live&&Powered&&Application.isFocused?session.settings.sfx*.075f:0;engine.volume=volume;engine.pitch=.7f+body.linearVelocity.magnitude*.045f+Mathf.Abs(command.y)*.12f;if(volume>.001f){if(!engine.isPlaying)engine.Play();}else engine.Stop();}
 public void StopSound(){if(engine!=null)engine.Stop();}void OnDisable(){StopSound();}
}
}
